 res=page.evaluate('''()=>{let checks=0;const ck=(b,m)=>{if(!b)throw Error(m);checks++};const eq=(a,b)=>{const k=x=>JSON.stringify(Object.entries(x).sort());return k(a)===k(b)};let intervals=0;for(const item of technologyData){for(let a=0;a<=item.rows.length;a++){for(let b=a;b<=item.rows.length;b++){const c=TechnologyCore.calc(item,a,b,100),rs=item.rows.slice(a,b),cost={};let time=0,xp=0;for(const r of rs){for(const x of r.cost||[])cost[x.t]=(cost[x.t]||0)+x.c;time+=r.tm||0;xp+=r.xp||0}ck(eq(cost,c.costs),'cost '+item.id);ck(c.time===time&&c.adjusted===Math.ceil(time/2),'time '+item.id);ck(c.xp===xp,'xp '+item.id);ck(c.rows.length===b-a,'range '+item.id);intervals++} }const max=item.rows.length;const plan=TechnologyCore.plan({[item.id]:[0,max]},item.group,0,true);ck(plan.selected.some(x=>x.id===item.id&&x.to===max),'plan '+item.id);ck(Object.keys(plan.requires).length===0,'requirements '+item.id)}for(const lang of techLanguages){for(const item of technologyData){ck(techName(item,lang)&& (lang==='en'||techNames[item.base]?.[lang]),'name '+lang+' '+item.id);const id=item.rows[0].eg||item.rows[0].eff?.t;if(id){const v=technologyEffectNames[id];ck(!!techEffectName(id,lang),'effect '+lang+' '+id);ck(lang==='en'||!!(techEffectTranslations[v]?.[lang]??techNames[techEffectAliases[v]??v]?.[lang]),'effect translation '+lang+' '+v)}}}return {checks,intervals,items:technologyData.length,icons:Object.keys(technologyArt).length}}''')
 print('CORE',res)
 result=page.evaluate('''()=>{let checks=0;const ck=(b,m)=>{if(!b)throw Error(m);checks++};const root=document.querySelector('#technologyRoot'),lang=document.querySelector('#language');const clean=()=>!(/\\b(?:undefined|NaN|Infinity)\\b/.test(root.textContent));for(const l of techLanguages){lang.value=l;lang.onchange();for(const [g,n] of [['academy',93],['garage',9],['alliance',25]]){tech.go('catalog');const tabs=[...root.querySelectorAll('.tech-tabs button')];tabs[['academy','garage','alliance'].indexOf(g)].click();ck(root.querySelectorAll('[data-tech-id]').length===n,l+' '+g+' count');for(const item of technologyData.filter(x=>x.group===g)){tech.go('detail',item.id);const selects=root.querySelectorAll('.tech-fields select');ck(selects.length===2,l+' '+item.id+' selects');selects[1].value=String(item.rows.length);selects[1].onchange();ck(clean(),l+' '+item.id+' clean');ck(selects[1].options.length===item.rows.length+1,l+' '+item.id+' levels');const img=root.querySelector('.tech-profile img');ck(!!img===!!item.icon,l+' '+item.id+' art');selects[0].value=String(item.rows.length);selects[0].onchange();ck(clean(),l+' '+item.id+' max');selects[0].value='0';selects[0].onchange();}tech.go('plan');ck(clean(),l+' '+g+' plan');tech.go('catalog');const q=root.querySelector('input[type=search]');q.value='zzzzz-no-match';q.oninput();ck(root.querySelectorAll('[data-tech-id]').length===0,l+' '+g+' search');q.value='';q.oninput();}}return {checks,locales:techLanguages.length}}''')
